'use strict';
const app=document.getElementById('app');
const KEY='working-day-v1-0-2';
const fresh=()=>({done:[],paths:{},checks:{},reviewed:[],assessment:null,save:false,work:{},quizDraft:null});
let state=fresh(),storageAvailable=true,saveFailed=false,clearFailed=false,otherTabChanged=false,lastStoredText=null,unrecognisedSaved=false,resumeRoute=null,officeGuide=false,officeSaveOpener=null;
function recoverSaved(raw){const out=fresh();if(!raw||typeof raw!=='object'||raw.save!==true)return out;out.save=true;out.work={};if(raw.work?.setupChecked===true)out.work.setupChecked=true;if(raw.quizDraft&&typeof raw.quizDraft==='object'){const answers={};for(let i=0;i<ASSESSMENT.length;i++){const v=raw.quizDraft.answers?.[i];if(Number.isInteger(v)&&v>=0&&v<ASSESSMENT[i].options.length)answers[i]=v;}const index=raw.quizDraft.index;out.quizDraft={answers,index:Number.isInteger(index)&&index>=0&&index<ASSESSMENT.length?index:0};}if(raw.work?.inspections&&typeof raw.work.inspections==='object'){out.work.inspections={};for(const id of ['payroll','mfa','supplier','converter']){const v=raw.work.inspections[id];if(Array.isArray(v))out.work.inspections[id]=[...new Set(v.filter(n=>Number.isInteger(n)&&n>=0&&n<3))];}}if(raw.work?.reportBuilt===true)out.work.reportBuilt=true;if(['routine','verify','urgent'].includes(raw.work?.triage))out.work.triage=raw.work.triage;out.done=Array.isArray(raw.done)?EVENTS.filter(e=>raw.done.includes(e.id)).map(e=>e.id):[];out.reviewed=Array.isArray(raw.reviewed)?MODULES.filter(m=>raw.reviewed.includes(m.id)).map(m=>m.id):[];for(const m of MODULES){const checks=raw.checks?.[m.id];out.checks[m.id]=Array.isArray(checks)?CHECKS[m.id].map((_,i)=>checks[i]===true):[];}for(const e of EVENTS){const path=raw.paths?.[e.id];out.paths[e.id]=[];if(!Array.isArray(path))continue;let from=e.start;for(const step of path.slice(0,50)){const node=e.nodes[from];if(!node?.choices)break;const choice=node.choices.find(c=>c[1]===step?.to&&c[0]===step?.label);if(!choice)break;out.paths[e.id].push({from,to:choice[1],label:choice[0]});from=choice[1];}}const a=raw.assessment;if(a&&Array.isArray(a.answers)&&a.answers.length===ASSESSMENT.length&&a.answers.every((v,i)=>Number.isInteger(v)&&v>=0&&v<ASSESSMENT[i].options.length)&&typeof a.date==='string'&&Number.isFinite(Date.parse(a.date))){out.assessment={answers:a.answers,score:a.answers.reduce((n,v,i)=>n+(v===ASSESSMENT[i].answer?1:0),0),date:a.date};}if(raw.work===undefined&&out.done.includes('report'))out.work.reportBuilt=true;return out;}
// Compatible 1.0 patch releases share this progress schema; future major/minor or patch records stay untouched.
function compatibleSavedVersion(version){const current=/^1\.0\.(\d+)$/.exec(META.version),saved=typeof version==='string'?/^1\.0\.(\d+)$/.exec(version):null;return !!(current&&saved&&Number(saved[1])>=2&&Number(saved[1])<=Number(current[1]));}
try{const text=localStorage.getItem(KEY);lastStoredText=text;if(text&&text.length<1000000){const saved=JSON.parse(text);if(compatibleSavedVersion(saved?.version)){state=recoverSaved(saved.state);if(validOfficeRoute(saved.workspace?.route))resumeRoute=saved.workspace.route;officeGuide=saved.workspace?.guide===true;}else unrecognisedSaved=true;}else if(text)unrecognisedSaved=true;}catch(error){if(error instanceof DOMException)storageAvailable=false;else unrecognisedSaved=true;}

let reviewIndex=0;
let assessmentAnswers=state.quizDraft?.answers||{},quizSubmitted=false,showTasks=false,quizIndex=state.quizDraft?.index||0,inspectState=state.work?.inspections||{},reportDraft=[],workStage={};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){if(unrecognisedSaved){state.save=false;syncOfficeSaving();return;}if(state.save){try{const existing=localStorage.getItem(KEY);if(existing!==lastStoredText){pauseSavingForTab();return;}const text=JSON.stringify({version:META.version,state,workspace:{route:route(),guide:officeGuide}});localStorage.setItem(KEY,text);lastStoredText=text;}catch{storageAvailable=false;state.save=false;saveFailed=true;showSaveFailure();syncOfficeSaving();}}}
function showTabWarning(){if(!otherTabChanged||document.getElementById('tab-warning'))return;const main=document.getElementById('main');if(!main)return;const warning=document.createElement('p');warning.id='tab-warning';warning.className='notice';warning.setAttribute('role','status');warning.textContent='Saved progress changed in another tab. Saving is off here to avoid overwriting it. Keep only one course tab open, then reload this tab to use the latest saved progress. Current unsaved work here may be lost on reload.';main.prepend(warning);}
function pauseSavingForTab(){otherTabChanged=true;state.save=false;showTabWarning();const toggle=document.getElementById('remember');if(toggle){toggle.checked=false;toggle.disabled=true;}syncOfficeSaving();const hint=document.getElementById('save-state');if(hint)hint.textContent='Saving is off here because another tab changed saved progress.';}
window.addEventListener('storage',event=>{if(event.key!==KEY&&event.key!==null)return;try{if(localStorage.getItem(KEY)!==lastStoredText)pauseSavingForTab();}catch{storageAvailable=false;state.save=false;saveFailed=true;showSaveFailure();syncOfficeSaving();}});
function clearStoredProgress(){if(unrecognisedSaved){state.save=false;syncOfficeSaving();say('Unrecognised saved work has not been changed.');return false;}try{if(localStorage.getItem(KEY)!==lastStoredText){pauseSavingForTab();return false;}localStorage.removeItem(KEY);if(localStorage.getItem(KEY)!==null)throw Error('delete readback mismatch');lastStoredText=null;clearFailed=false;return true;}catch{clearFailed=true;state.save=false;storageAvailable=false;showClearFailure();syncOfficeSaving();return false;}}
function showClearFailure(){if(!clearFailed||document.getElementById('clear-failure'))return;const main=document.getElementById('main');if(!main)return;const warning=document.createElement('p');warning.id='clear-failure';warning.className='notice';warning.setAttribute('role','status');warning.textContent='Saved progress could not be removed from this browser. Saving is off for this page, but older progress may return after reload. Clear this site in your browser settings before leaving a shared device.';main.prepend(warning);}
function showSaveFailure(){showTabWarning();showClearFailure();if(!saveFailed||document.getElementById('save-failure'))return;const main=document.getElementById('main');if(!main)return;const warning=document.createElement('p');warning.id='save-failure';warning.className='notice save-warning';warning.setAttribute('role','status');warning.textContent='Saving stopped in this browser. Your work is still on this page, but closing or reloading may lose recent progress. Keep this page open. If saved work cannot be removed on a shared device, clear this site in browser settings before leaving.';main.prepend(warning);}
function say(text){document.getElementById('announce').textContent=text;}
function route(){try{return decodeURIComponent(location.hash.slice(1)||'home');}catch{return 'home';}}
function setPage(html){if(route()==='day'||route().startsWith('day/'))html=html.replace(/<h3(?=[ >])/g,'<h2').replace(/<\/h3>/g,'</h2>');document.body.dataset.route=route().split('/')[0];document.getElementById('office-menu').hidden=true;document.getElementById('office-menu-toggle').setAttribute('aria-expanded','false');app.innerHTML=`<div class="office-shell"><nav class="office-folders" aria-label="Workspace"><p class="office-label">Today</p><a href="#day">Current work</a><a href="#library">Learning notebook</a><a href="#assessment">Learning record</a><p class="office-label">Keep nearby</p><a href="#practice">Practice desk</a><a href="#team">Team setup</a><a href="#manager">Reporting card</a><a href="Learning-Transcript.html">Reading version</a></nav><main id="main" tabindex="-1">${html}</main><aside id="office-guide" aria-label="Optional guide" ${officeGuide?'':'hidden'}><p class="office-label">A little guidance</p><h2>Take your time.</h2><p>This is practice, not a real account. Inspect the request and use the known records before choosing.</p><p>No real message, payment or report is sent.</p><button id="office-guide-hide">Hide guide</button></aside></div>`;document.querySelector('.office-shell').classList.toggle('office-guide-closed',!officeGuide);document.getElementById('office-guide-hide').onclick=()=>{officeGuide=false;updateOfficeGuide();document.getElementById('office-menu-toggle').focus();};document.querySelectorAll('.office-folders a').forEach(a=>{if(a.hash.slice(1)===route().split('/')[0])a.setAttribute('aria-current','page');});syncOfficeSaving();document.querySelectorAll('.top nav a').forEach(a=>{if((a===document.querySelector('.top nav a:nth-child(2)')&&['day','library','assessment','practice'].includes(route().split('/')[0]))||a.hash.slice(1)===route().split('/')[0])a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const courseLink=document.querySelector('.top nav a:nth-child(2)');const nextTask=EVENTS.find(e=>!state.done.includes(e.id)),nextMod=MODULES.find(m=>!state.reviewed.includes(m.id)||!checksComplete(m.id));courseLink.href=nextTask?'#day/'+nextTask.id:nextMod?'#library/'+nextMod.id:'#assessment';document.title=(route().startsWith('day')?'Working day':route().startsWith('library')?'Learning library':route()==='team'?'Run with your team':route()==='manager'?'Manager intake':route()==='practice'?'Practice desk':route()==='assessment'?'Assessment':route()==='help'?'Help & sources':'Overview')+' | The Working Day';document.getElementById('main').focus({preventScroll:true});window.scrollTo(0,0);showSaveFailure();}
const progress=()=>{const modules=MODULES.filter(m=>state.reviewed.includes(m.id)&&checksComplete(m.id)).length,passed=state.assessment?.score>=13;return `<section class="course-progress" aria-label="Whole-course progress"><div class="progress-label"><strong>Course progress</strong><span>${state.done.length+modules+(passed?1:0)} of 19 stages complete</span></div><progress max="19" value="${state.done.length+modules+(passed?1:0)}" aria-label="Whole-course completion"></progress><div class="progress-stages"><a href="#day">Working day: ${state.done.length}/10 tasks</a><a href="#library">Learning: ${modules}/8 modules</a><a href="#assessment">Assessment: ${passed?'complete':state.assessment?'review needed':'not complete'}</a></div></section>`;};
const sourceLinks=ids=>ids.map(id=>{const s=SOURCES.find(x=>x[0]===id);return `<a href="${esc(s[2])}" target="_blank" rel="noopener noreferrer">${esc(s[1])}</a>`;}).join(' · ');
function render(){const r=route();if(r==='home')home();else if(r==='day'||r.startsWith('day/'))day(r.split('/')[1]);else if(r==='library')library();else if(r.startsWith('library/'))moduleView(r.split('/')[1]);else if(r==='manager')manager();else if(r==='team')team();else if(r==='practice')practice();else if(r==='assessment')assessment();else if(r==='help')help();else home();}
function home(){const next=EVENTS.find(e=>!state.done.includes(e.id))||EVENTS[0],nextModule=MODULES.find(m=>!state.reviewed.includes(m.id)||!checksComplete(m.id));setPage(`<section class="hero compact-hero"><h1>A normal day.<br>A few unusual requests.</h1><p class="lead">A fictional working day for UK small-business staff. Handle unusual requests, make a choice and see what happens.</p><div class="actions"><a class="button primary" href="${state.done.length===10?(nextModule?'#library/'+nextModule.id:'#assessment'):'#day/'+next.id}">${state.assessment?.score>=13?'View your learning record':state.done.length?'Continue course':'Start the working day'}</a><a class="button" href="#team">Run with your team</a></div><p class="hint">10 tasks, 8 learning modules, then an assessment. No timer.</p></section>${state.done.length||state.reviewed.length||state.assessment?progress():''}<details class="before-start"><summary>Before you begin at work</summary><p>Know your reporting contact, urgent/backup route and approved tools. Follow your organisation's policies.</p><p>Allow about 45-60 minutes plus discussion. This is an untested estimate; take breaks or use the <a href="Learning-Transcript.html">reading version</a>.</p><p>No real messages, payments or reports are sent. Do not enter real passwords, customer data or live security problem details.</p></details>`);}
function currentNode(e){const path=state.paths[e.id]||[];return path.length?path[path.length-1].to:e.start;}
function day(id){const event=EVENTS.find(e=>e.id===id)||EVENTS.find(e=>!state.done.includes(e.id))||EVENTS[0];const node=event.nodes[currentNode(event)]||event.nodes[event.start];const path=state.paths[event.id]||[];const index=EVENTS.indexOf(event);const module=MODULES.find(m=>m.id===event.module);setPage(`${delayedFollowups(event.id)}<div class="day-layout"><aside aria-label="Working day tasks"><div class="task-toolbar"><p>Task ${index+1} of 10</p><button id="toggle-tasks" class="task-toggle" aria-expanded="${showTasks}">${showTasks?'Return to current task':'All tasks'}</button></div><div class="tasklist ${!showTasks?'collapsed':''}">${EVENTS.map(e=>`<button class="task ${e.id===event.id?'selected':''}" data-task="${e.id}" ${e.id===event.id?'aria-current="step"':''}><span class="meta">${e.time} · ${esc(e.channel)} ${state.done.includes(e.id)?'· Complete':''}</span><span class="subject">${esc(e.subject)}</span></button>`).join('')}</div></aside><article class="message" aria-labelledby="task-title"><div class="message-head"><h1 id="task-title">${esc(event.subject)}</h1><p class="meta">${event.time} · ${esc(event.channel)}</p></div>${path.length||workStage[event.id]?`<details class="task-context"><summary>Original request</summary><p>${esc(SHORT_INTROS[event.id]||event.intro)}</p>${messageArtifact(event.id)}</details>`:`<p>${esc(SHORT_INTROS[event.id]||event.intro)}</p>${CLUES[event.id]||event.id==='ai'&&!state.work?.triage||event.id==='workspace'&&!state.work?.setupChecked?'':messageArtifact(event.id)}`}${path.length||workStage[event.id]?'':gameGlossary(event.id)}${activeWork(event,node,path)}<section class="decision" aria-live="polite" ${workPending(event,path)?'hidden':''}><p class="eyebrow">${node.end?'Outcome':'Decision '+(path.length+1)}</p><h3>${esc(shortNode(event,node))}</h3>${node.lesson?`<details class="why"><summary>Why this matters</summary><p>${esc(node.lesson)}</p></details>`:''}</section>${node.end&&event.id==='report'&&!state.work?.reportBuilt?'':node.end?`<div class="actions"><button id="restart-task" class="text-link">Try another route</button>${index<EVENTS.length-1?`<a class="button primary" href="#day/${EVENTS[index+1].id}">Next task</a>`:'<a class="button primary" href="#library">Review the learning modules</a>'}</div>`:`<div class="choices" role="group" aria-label="Choose your response" ${workPending(event,path)?'hidden':''}>${node.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><span class="letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${esc(c[0])}</span></button>`).join('')}</div>`}
${path.length?`<details><summary>Your decision trail (${path.length} choices)</summary><ol>${path.map(p=>`<li>${esc(p.label)}</li>`).join('')}</ol></details>`:''}<details><summary>Related learning</summary><a href="#library/${module.id}">${esc(module.title)}</a></details></article></div>`);
bindWork(event);setOfficeTaskList(showTasks,false);document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{showTasks=false;if(event.id===b.dataset.task){setOfficeTaskList(false,true);}else location.hash='day/'+b.dataset.task;});document.getElementById('toggle-tasks').onclick=()=>{setOfficeTaskList(!showTasks,true);};document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const c=node.choices[Number(b.dataset.choice)];state.paths[event.id]=[...path,{from:currentNode(event),to:c[1],label:c[0]}];if(event.nodes[c[1]].end&&(event.id!=='report'||state.work?.reportBuilt)&&!state.done.includes(event.id))state.done.push(event.id);save();day(event.id);const decision=document.querySelector('.decision');decision.setAttribute('tabindex','-1');decision.focus({preventScroll:true});decision.scrollIntoView({block:'nearest'});say(event.nodes[c[1]].end?'Task complete.':'Your decision outcome is now shown.');});const restart=document.getElementById('restart-task');if(restart)restart.onclick=()=>{state.paths[event.id]=[];workStage[event.id]=false;inspectState[event.id]=[];if(event.id==='workspace')state.work.setupChecked=false;if(event.id==='report'){state.work.reportBuilt=false;reportDraft=[];}if(event.id==='ai')delete state.work.triage;if(state.work.inspections)delete state.work.inspections[event.id];save();day(event.id);say('Scenario restarted. Repeat the practice actions; earned completion is retained.');};}
function library(){const nextTask=EVENTS.find(e=>!state.done.includes(e.id)),nextModule=MODULES.find(m=>!state.reviewed.includes(m.id)||!checksComplete(m.id));const nextHref=nextTask?'#day/'+nextTask.id:nextModule?'#library/'+nextModule.id:'#assessment',nextLabel=nextTask?'Continue the working day':nextModule?'Continue learning':'Open your assessment';setPage(`<div class="section-head"><p class="eyebrow">Learning modules</p><h1>Understand the habit behind the choice.</h1><p>Read each module, answer its two checks, then finish it to continue.</p></div><section class="panel" aria-labelledby="learning-next"><h2 id="learning-next">Your next step</h2><p>${nextTask?'Finish the working-day tasks first. You can still browse the modules below.':nextModule?esc(nextModule.title):'Your practice and module checks are complete. Take the assessment or review your result.'}</p><a class="button primary" href="${nextHref}">${nextLabel}</a></section><details class="progress-disclosure"><summary>Your course progress</summary>${progress()}</details><details class="module-browser"><summary>Browse all 8 modules</summary><p class="hint">You can revisit any module. The assessment unlocks after all tasks, modules and checks are complete.</p><div class="grid">${MODULES.map((m,i)=>`<section class="panel module-card"><p class="eyebrow">Module ${String(i+1).padStart(2,'0')}</p><a href="#library/${m.id}">${esc(m.title)}</a><p>${esc(m.goal)}</p><p class="meta">${state.reviewed.includes(m.id)&&checksComplete(m.id)?'Finished':`${(state.checks[m.id]||[]).filter(Boolean).length}/2 checks correct`}</p></section>`).join('')}</div></details>`);}

function moduleView(id){const m=MODULES.find(m=>m.id===id);if(!m)return library();const i=MODULES.indexOf(m);setPage(`<div class="module-content"><p class="breadcrumb"><a href="#library">All modules</a></p><p class="eyebrow">Module ${i+1} of 8</p><h1 id="module-top" tabindex="-1">${esc(m.title)}</h1><p class="lead">${esc(m.goal)}</p><nav class="module-jumps no-print" aria-label="On this module"><a href="#library/${m.id}" id="jump-learning">Learning</a><a href="#library/${m.id}" id="jump-checks">Practice checks</a></nav><p class="hint" id="module-check-status">${(state.checks[m.id]||[]).filter(Boolean).length} of 2 checks correct${state.reviewed.includes(m.id)&&checksComplete(m.id)?' · Module finished':''}</p><div id="module-learning">${moduleSections(m)}<div class="actions no-print"><button class="primary" id="start-module-checks">Continue to practice checks</button></div></div><section id="module-practice" hidden><h2 id="practice-heading" tabindex="-1">Practice checks</h2><p>Answer both checks, then finish the module.</p><p><a href="#library/${m.id}" id="back-learning" class="no-print">Back to the learning</a></p>${CHECKS[m.id].map((c,j)=>`<div class="check" id="check-${j}"><h3>${j+1}. ${esc(c[0])}</h3><div class="choices">${c[1].map((opt,k)=>`<button class="choice" data-check="${j}" data-option="${k}">${esc(opt)}</button>`).join('')}</div><div id="feedback-${j}" aria-live="polite">${state.checks[m.id]?.[j]?`<div class="feedback"><strong>Correct.</strong> ${esc(c[3])}</div>`:''}</div></div>`).join('')}<button id="review-module" class="primary" ${checksComplete(m.id)?'':'disabled'}>${state.reviewed.includes(m.id)?'Continue to '+(i<MODULES.length-1?'next module':'assessment'):'Finish module and continue'}</button><p class="hint">Both checks must be correct to finish.</p></section><details class="rule"><summary>Sources and related practice</summary><p><a href="#day/${EVENTS.find(e=>e.module===m.id)?.id||'workspace'}">Practise this in the working day</a></p><p class="hint">${sourceLinks(m.sources)}</p></details></div>`);
function showModulePart(checks){document.getElementById('module-learning').hidden=checks;document.getElementById('module-practice').hidden=!checks;document.getElementById('jump-learning').setAttribute('aria-current',checks?'false':'step');document.getElementById('jump-checks').setAttribute('aria-current',checks?'step':'false');const h=document.getElementById(checks?'practice-heading':'module-top');h.focus({preventScroll:true});h.scrollIntoView({block:'start'});}for(const [id,checks] of [['jump-checks',true],['jump-learning',false],['back-learning',false],['start-module-checks',true]])document.getElementById(id).onclick=e=>{e.preventDefault();showModulePart(checks);};document.getElementById('jump-learning').setAttribute('aria-current','step');
document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{const j=Number(b.dataset.check),k=Number(b.dataset.option),c=CHECKS[m.id][j],right=k===c[2];if(!state.checks[m.id])state.checks[m.id]=[];if(right)state.checks[m.id][j]=true;save();document.getElementById('feedback-'+j).innerHTML=`<div class="feedback ${right?'':'wrong'}"><strong>${right?'Correct.':'Review this choice.'}</strong> ${esc(c[3])}${right?'':' Try again.'}</div>`;document.getElementById('review-module').disabled=!checksComplete(m.id);const checkStatus=(state.checks[m.id]||[]).filter(Boolean).length+' of 2 checks correct'+(state.reviewed.includes(m.id)&&checksComplete(m.id)?' · Module finished':'');document.getElementById('module-check-status').textContent=checkStatus;say((right?'Correct. ':'Review this choice. ')+c[3]+(right?'':' Try again.')+' '+checkStatus+'.');});document.getElementById('review-module').onclick=()=>{if(!checksComplete(m.id))return;if(!state.reviewed.includes(m.id))state.reviewed.push(m.id);save();location.hash=i<MODULES.length-1?'library/'+MODULES[i+1].id:'assessment';say('Module finished. Continuing.');};}
function checksComplete(id){return CHECKS[id].every((_,i)=>state.checks[id]?.[i]===true);}
function ready(){return EVENTS.every(e=>state.done.includes(e.id))&&MODULES.every(m=>state.reviewed.includes(m.id)&&checksComplete(m.id));}
function assessment(){if(state.assessment&&quizSubmitted===false)return result();if(!ready()){const tasks=EVENTS.filter(e=>!state.done.includes(e.id)),mods=MODULES.filter(m=>!state.reviewed.includes(m.id)||!checksComplete(m.id));setPage(`<div class="section-head"><p class="eyebrow">Final assessment</p><h1>Finish the practice first.</h1><p>Complete these remaining steps to unlock the assessment.</p></div><div class="grid"><section class="panel"><h2>Working day</h2><p>${tasks.length} tasks remaining.</p><ul>${tasks.map(e=>`<li><a href="#day/${e.id}">${esc(e.subject)}</a></li>`).join('')||'<li>All tasks complete.</li>'}</ul></section><section class="panel"><h2>Learning modules</h2><p>${mods.length} modules to review.</p><ul>${mods.map(m=>`<li><a href="#library/${m.id}">${esc(m.title)}</a> <span class="hint">${checksComplete(m.id)?'Checks passed; finish this module':`${(state.checks[m.id]||[]).filter(Boolean).length}/2 checks correct; review and finish`}</span></li>`).join('')||'<li>All modules reviewed.</li>'}</ul></section></div>`);return;}
setPage(`<div class="section-head"><p class="eyebrow">Final assessment · 16 questions</p><h1>What would you do next?</h1><p>Answer all 16 questions. The course-chosen target is 13 correct. No timer; retakes are welcome.</p></div><form id="quiz" novalidate>${ASSESSMENT.map((q,i)=>`<fieldset class="quiz-question" data-quiz-question="${i}" ${i!==quizIndex?'hidden':''}><legend tabindex="-1" id="quiz-legend-${i}">${i+1}. ${esc(q.q)}</legend>${q.options.map((opt,k)=>`<label><input type="radio" name="q${i}" aria-describedby="quiz-error" value="${k}" ${assessmentAnswers[i]===k?'checked':''}><span>${esc(opt)}</span></label>`).join('')}</fieldset>`).join('')}<p class="hint" id="quiz-position">Question ${quizIndex+1} of 16</p><p id="quiz-error" class="error" role="alert"></p><div class="actions"><button type="button" id="quiz-back" class="text-link" ${quizIndex===0?'hidden':''}>Previous</button><button class="primary" type="submit">${quizIndex===15?'Submit assessment':'Next question'}</button></div></form>`);
document.getElementById('quiz-legend-'+quizIndex).focus({preventScroll:true});
document.getElementById('quiz-back').onclick=()=>{quizIndex=Math.max(0,quizIndex-1);saveQuizDraft();assessment();};document.getElementById('quiz').onchange=e=>{if(e.target.name?.startsWith('q')){assessmentAnswers[Number(e.target.name.slice(1))]=Number(e.target.value);document.getElementById('quiz-error').textContent='';e.target.closest('fieldset').removeAttribute('aria-invalid');saveQuizDraft();}};document.getElementById('quiz').onsubmit=e=>{e.preventDefault();if(!Number.isInteger(assessmentAnswers[quizIndex])){document.getElementById('quiz-error').textContent='Choose an answer to continue.';document.querySelector(`[data-quiz-question="${quizIndex}"]`).setAttribute('aria-invalid','true');document.querySelector(`input[name="q${quizIndex}"]`).focus();return;}if(quizIndex<15){quizIndex++;saveQuizDraft();assessment();return;}const missing=ASSESSMENT.map((_,i)=>i).filter(i=>!Number.isInteger(assessmentAnswers[i]));if(missing.length){quizIndex=missing[0];saveQuizDraft();assessment();document.getElementById('quiz-error').textContent=`Answer all questions before submitting. ${missing.length} unanswered. First: question ${missing[0]+1}.`;document.querySelector(`input[name="q${missing[0]}"]`).focus();return;}const answers=ASSESSMENT.map((_,i)=>assessmentAnswers[i]);const score=answers.reduce((n,a,i)=>n+(a===ASSESSMENT[i].answer?1:0),0);state.assessment={answers,score,date:new Date().toISOString()};state.quizDraft=null;quizSubmitted=false;reviewIndex=0;save();result();};}
function missedReview(a){const missed=ASSESSMENT.map((q,i)=>({q,i})).filter(({q,i})=>a.answers[i]!==q.answer);if(!missed.length)return '';reviewIndex=Math.min(Math.max(0,reviewIndex),missed.length-1);const {q,i}=missed[reviewIndex];return `<section class="panel no-print" id="missed-review" aria-labelledby="missed-title"><h2 id="missed-title" tabindex="-1">Review missed answers</h2><p class="hint">${missed.length} to revisit. Review ${reviewIndex+1} of ${missed.length} · Question ${i+1}</p><h3>${esc(q.q)}</h3><p>Your answer: ${esc(q.options[a.answers[i]])}</p><p><strong>Best answer:</strong> ${esc(q.options[q.answer])}</p><p>${esc(q.why)}</p><div class="actions"><button class="text-link" id="missed-back" ${reviewIndex===0?'hidden':''}>Previous missed answer</button>${reviewIndex<missed.length-1?'<button class="primary" id="missed-next">Next missed answer</button>':'<p class="hint">You have reached the last missed answer. Review a module or retake when ready.</p>'}</div><a href="#library/${q.module}">Review this learning module</a></section>`;}
function bindMissedReview(a){for(const [id,step] of [['missed-back',-1],['missed-next',1]]){const button=document.getElementById(id);if(button)button.onclick=()=>{reviewIndex+=step;result();document.getElementById('missed-title').focus();document.getElementById('missed-review').scrollIntoView({block:'start'});};}}
function result(){const a=state.assessment;if(!a)return assessment();const passed=a.score>=13;setPage(`<section class="result ${passed?'':'fail'}"><p class="eyebrow">Assessment result</p><h1>${passed?'Learning standard met.':'Review, then try again.'}</h1><p class="score">${a.score} / 16 <span class="meta">(${Math.round(a.score/16*100)}%)</span></p><p>${passed?'You completed the working day, learning modules and final assessment. Review the answer feedback below and agree one useful habit with your manager.':'The target is 13/16. Review the feedback and linked modules, then take another attempt when ready. No time limit or score penalty.'}</p><div class="actions"><button id="retake" class="${passed?'text-link':'primary'}">Retake assessment</button></div></section>${passed?`${useAtWork()}<section class="no-print panel"><h2>Your completion record</h2><p>Optional name, used only for printing and not saved. On a shared device, leave it blank.</p><label class="field" for="learner-name">Name for this record (optional)</label><input type="text" id="learner-name" maxlength="100" autocomplete="off" placeholder="Leave blank for an unnamed record"><button class="primary" id="print-record">Print or save record as PDF</button></section><section class="certificate" aria-label="Completion record"><p class="eyebrow">Record of learning completion</p><h2>The Working Day</h2><p>Workplace security awareness</p><p id="certificate-name" class="learner">Learner</p><p>Completed 10 simulated workplace tasks, 8 learning modules and the final assessment.</p><p><strong>Assessment: ${a.score}/16 · ${Math.round(a.score/16*100)}%</strong><br>Date: ${esc(new Date(a.date).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}))}<br>Course version ${META.version}</p><p>${esc(META.publisher)}</p><p class="legal">Learning record made in this browser. Name and result are not checked by someone independent.<br>Not an officially recognised qualification, approved UK National Cyber Security Centre training or formal Cyber Essentials approval.<br>Law and guidance checked ${META.checked}.</p></section>`:''}${missedReview(a)}<details class="rule no-print"><summary>Review all 16 answers</summary>${ASSESSMENT.map((q,i)=>`<div class="review ${a.answers[i]===q.answer?'':'wrong'}"><h3>${i+1}. ${esc(q.q)}</h3><p><strong>${a.answers[i]===q.answer?'Correct':'Review'}</strong> · Your answer: ${esc(q.options[a.answers[i]])}</p>${a.answers[i]!==q.answer?`<p>Best answer: ${esc(q.options[q.answer])}</p>`:''}<p>${esc(q.why)}</p><a href="#library/${q.module}">Review the learning module</a></div>`).join('')}</details>`);
bindMissedReview(a);
document.getElementById('retake').onclick=()=>{state.assessment=null;state.quizDraft=null;assessmentAnswers={};quizSubmitted=true;quizIndex=0;save();assessment();say('New assessment attempt started.');};if(passed){document.getElementById('learner-name').oninput=e=>document.getElementById('certificate-name').textContent=e.target.value.trim()||'Learner';document.getElementById('print-record').onclick=()=>{document.body.classList.add('print-certificate');window.print();document.body.classList.remove('print-certificate');};}}
function help(){setPage(`<div class="section-head"><p class="eyebrow">Help, privacy and sources</p><h1>Know what this course does.<br>And what it does not.</h1><p>Plain-English support for learners and managers. No account or technical background is needed.</p></div><div class="module-content"><details><summary>What the course does and does not prove</summary><p>Awareness practice, not an officially recognised qualification, UK National Cyber Security Centre-approved training, formal Cyber Essentials approval or a promise that legal requirements are met. The record does not prove who completed the course and can be changed by the learner. This is not a plan for handling security problems. A live concern must not wait for training.</p><p>All in-game people and actions are fictional; no messages, payments or reports are sent. Do not enter real passwords, customer data or security problem details.</p></details><details><summary>How to use the course</summary><p>Start with the overview, play the 10 working-day tasks, read the 8 modules and complete their checks. Press Finish module and continue after both checks. Then take the 16-question assessment. There is no timer; breaks and paired discussion are welcome. You do not need to explore every branch to finish a task.</p><p><a href="Learning-Transcript.html">Reading version</a> · <a href="#practice">Optional practice desk</a>. It includes the reference notes and task cards and possible outcomes for assisted or offline discussion.</p></details><details><summary>Useful meanings</summary><dl><dt><strong>Extra sign-in check</strong></dt><dd>An extra check beyond your password, such as a code or approval request. Only approve a sign-in you started. Some checks can still be misused if a criminal tricks you.</dd><dt><strong>Private-network connection (VPN)</strong></dt><dd>Your organisation's approved connection to work systems. It does not make every website, download or request safe, or stop nearby people hearing a call.</dd><dt><strong>Personal information</strong></dt><dd>Information about someone who can be identified, including many staff and customer records.</dd><dt><strong>Reporting contact</strong></dt><dd>The person or team your workplace asks you to tell about security concerns. Agree a backup and an urgent route before using the course.</dd></dl></details><details><summary>Privacy and saving progress</summary><p>The course does not send activity or results to us or an employer. Optional progress is stored only in this browser on this device. It has no advertising or account login. Progress stays here while the page is open unless you choose to save it in this browser. Optional saved progress includes choices, inspected details and setup checks, module checks, unfinished assessment answers, current question, result and date, but not the name entered for a completion record.</p><p>The hosting provider may process normal request information such as internet address and browser details under its own policy. Source links open third-party sites in another tab; their own privacy policies apply. Offline use does not need an internet connection except to open those source links.</p><p>Do not enable saving on a shared device. Reset progress using Save in the title bar or clear browser storage. A learner can change records kept in their browser. Nobody independently checks who completed the course.</p></details><details><summary>Support and accessibility</summary><p>Use Tab to move between links and buttons, and Enter or Space to activate them. Use arrow keys to move between assessment answers and Space to select. Text can be enlarged with browser zoom. No decision is timed and no drag-and-drop is required. The reading version supports individual or assisted learning. This is not a claim of formal approval against an accessibility standard; organisations should check usability with their own learners and provide support where needed.</p></details><details><summary>For managers</summary><p><a href="#team">Run this with your team</a>: start with the short setup route. Brief your team on real local contacts and policies before play. <a href="#manager">Use the manager card for receiving a security report</a> to rehearse receiving a report. Use the <a href="Facilitator-Guide.pdf">facilitator guide (PDF)</a> or <a href="Facilitator-Guide.docx">editable guide (DOCX)</a>, adapt the contact sheet and explain any conduct rules. Welcome honest reports and focus on support and fixes. Do not treat a browser-made completion record as a central employer-held training record that cannot be changed by a learner. If formal records are needed, use an approved employer process with a clear explanation of what is recorded and why.</p></details><details><summary>Law and guidance currency</summary><p>Checked ${META.checked}. This course describes guidance checked on the date shown, not a forecast of 2027 law. The Cyber Security and Resilience (Network and Information Systems) Bill remains a Bill in the checked parliamentary record, not law. Review official sources before later deployment, with a planned review after 26 October 2026. The authorised team should assess data protection duties and any extra duties that apply to your kind of business.</p></details><details class="rule"><summary>Official sources</summary><p>Official guidance informs the habits. Scenarios and consequence branches are original teaching examples, not real incidents or quoted legal rules. No official body endorses this course.</p><ul class="sources">${SOURCES.map(s=>`<li><strong>${esc(s[0])}</strong> · <a href="${esc(s[2])}" target="_blank" rel="noopener noreferrer">${esc(s[1])}</a><br><span class="hint">${esc(s[3])}</span></li>`).join('')}</ul></details></div>`);}

function delayedFollowups(at){const messages=[];for(const [id,routes]of Object.entries(FOLLOWUPS)){const path=state.paths[id]||[];const end=path.length?path[path.length-1].to:null;if(end&&routes[end]?.at===at)messages.push(routes[end]);}return messages.length?`<aside class="followups" aria-label="Follow-ups from earlier choices">${messages.map(m=>`<details><summary>${esc(m.heading)}</summary><p>${esc(m.text)}</p></details>`).join('')}</aside>`:'';}
function gameGlossary(){return '';}
function messageArtifact(id){const a=ARTIFACTS[id];if(!a)return '';return `<aside class="artifact ${a.kind}" aria-label="${esc(a.label)}"><div class="artifact-bar"><span class="artifact-icon" aria-hidden="true">${a.kind==='email'?'@':a.kind==='chat'?'···':a.kind==='call'?'☎':'i'}</span><span>${esc(a.label)}</span></div><div class="artifact-body"><h3>${esc(a.heading)}</h3>${a.lines.map(t=>`<p>${esc(t)}</p>`).join('')}${a.qr?"<div class=\"qr-placeholder\" aria-label=\"Non-functional example scanning code\">square scanning code<br>example</div>":''}</div></aside>`;}
let triageState={},practiceIndex=0;
function focusPracticeCard(){const title=document.querySelector('[data-practice-card]:not([hidden]) h3');title.tabIndex=-1;title.focus();}
function practice(){setPage(`<div class="section-head"><p class="eyebrow">Optional practice desk</p><h1>Practise deciding.<br>Then build the report.</h1><p>Optional and unscored. Use the supplied practice facts only.</p></div><div class="module-content"><section><h2>1. Sort the desk</h2><p>Route one card at a time: normal work, check first, or report as soon as you can.</p>${TRIAGE.map((t,i)=>`<div class="check" data-practice-card="${i}" ${i!==practiceIndex?'hidden':''}><p class="eyebrow">Card ${i+1} of 6 · ${esc(t.from)}</p><h3>${esc(t.text)}</h3><div class="choices">${TRIAGE_LABELS.map((label,k)=>`<button class="choice" data-triage="${t.id}" data-answer="${k}">${esc(label)}</button>`).join('')}</div><div id="triage-feedback-${t.id}" aria-live="polite">${triageState[t.id]!==undefined?`<div class="feedback ${triageState[t.id]===t.answer?'':'wrong'}"><strong>${triageState[t.id]===t.answer?'Good next step.':'Review the next step.'}</strong> ${esc(t.feedback)}</div>`:''}</div></div>`).join('')}<div class="actions"><button id="practice-back" class="text-link" ${practiceIndex===0?'hidden':''}>Previous card</button><button id="practice-next" class="primary" ${(triageState[TRIAGE[practiceIndex].id]!==TRIAGE[practiceIndex].answer||practiceIndex===5)?'hidden':''}>Next card</button></div><p class="hint">These are teaching examples. Follow your local reporting rules, including when a concern is caught before harm is done.</p></section><details class="rule"><summary>Practise assembling a report</summary><div class="notice"><p><strong>Fictional facts:</strong> At 15:32, Taylor opened a login page from an unexpected email on their work laptop. They entered their work email password. They did not approve an extra sign-in check, download or run a file. They closed the page. They do not know whether anyone accessed the account.</p><p>Choose what belongs in the report. Nothing is submitted.</p></div><form id="report-builder"><fieldset class="quiz-question"><legend>When and what happened?</legend><label><input type="radio" name="report-time" aria-describedby="report-error" value="facts"><span>15:32: opened an unexpected email link and entered a work password.</span></label><label><input type="radio" name="report-time" aria-describedby="report-error" value="guess"><span>The whole business was definitely hacked.</span></label></fieldset><fieldset class="quiz-question"><legend>What else is known?</legend><label><input type="radio" name="report-actions" aria-describedby="report-error" value="facts"><span>No extra sign-in check was approved. No files were downloaded or run. Page closed. Account access is unknown.</span></label><label><input type="radio" name="report-actions" aria-describedby="report-error" value="secret"><span>Include Taylor's password and backup sign-in codes for testing.</span></label></fieldset><fieldset class="quiz-question"><legend>Where should it go?</legend><label><input type="radio" name="report-route" aria-describedby="report-error" value="trusted"><span>The known contact for reporting security concerns or getting help from your work computer support team, with an alternative if the account may be accessed or controlled without permission.</span></label><label><input type="radio" name="report-route" aria-describedby="report-error" value="broadcast"><span>Everyone in the company, with the suspicious link for them to try.</span></label></fieldset><p id="report-error" class="error" role="alert"></p><button class="primary" type="submit">Check and assemble the report</button></form><div id="report-result" aria-live="polite"></div></details>${changePanel()}<details class="rule"><summary>Discuss it with a colleague</summary><p>Tell a colleague in your own words why the right next step helps. If you need jargon to explain it, try again using a normal working-day example.</p><ul><li>Why is a caller's supplied number a weak way to check the same caller?</li><li>Why does your organisation's approved private-network connection (VPN) not solve an overheard customer call?</li><li>Why does reporting an honest mistake quickly help the team responsible for handling the concern?</li></ul></details></div>`);
bindChange();
document.getElementById('practice-back').onclick=()=>{practiceIndex=Math.max(0,practiceIndex-1);practice();focusPracticeCard();};document.getElementById('practice-next').onclick=()=>{practiceIndex=Math.min(5,practiceIndex+1);practice();focusPracticeCard();};document.querySelectorAll('[data-triage]').forEach(b=>b.onclick=()=>{const t=TRIAGE.find(t=>t.id===b.dataset.triage),k=Number(b.dataset.answer);triageState[t.id]=k;document.getElementById('triage-feedback-'+t.id).innerHTML=`<div class="feedback ${k===t.answer?'':'wrong'}"><strong>${k===t.answer?'Good next step.':'Review the next step.'}</strong> ${esc(t.feedback)}</div>`;document.getElementById('practice-next').hidden=k!==t.answer||practiceIndex===5;say(k===t.answer?'Good next step.':'Review the feedback.');});
document.getElementById('report-builder').onchange=e=>{document.getElementById('report-error').textContent='';document.getElementById('report-result').innerHTML='';e.target.closest('fieldset')?.removeAttribute('aria-invalid');};
document.getElementById('report-builder').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),values=['report-time','report-actions','report-route'].map(k=>data.get(k));if(values.some(v=>!v)){document.getElementById('report-result').innerHTML='';const names=['report-time','report-actions','report-route'];document.getElementById('report-error').textContent='Choose one option in each of the three sections.';names.forEach((name,i)=>e.target.querySelector(`input[name="${name}"]`).closest('fieldset').setAttribute('aria-invalid',String(!values[i])));e.target.querySelector(`input[name="${names[values.findIndex(v=>!v)]}"]`).focus();return;}document.getElementById('report-error').textContent='';if(values[0]!=='facts'||values[1]!=='facts'||values[2]!=='trusted'){document.getElementById('report-result').innerHTML="<div class=\"feedback wrong\"><h3>Keep it factual and controlled.</h3><p>Use the observed actions and time. Do not send passwords and sign-in codes, claim an attack without evidence or invite others to test the suspicious link. Revise the choices and try again.</p></div>";say('Review the report choices.');return;}document.getElementById('report-result').innerHTML="<div class=\"feedback\"><h3>A useful first report</h3><p>At 15:32, Taylor opened a sign-in page from an unexpected email on a work laptop and entered a work email password. They did not approve an extra sign-in check, download or run a file. They closed the page. Account access is unknown.</p><p>Please advise on regaining access through the genuine service and signing the account out on devices or apps where it is already signed in if needed. This is being raised through the known contact for reporting security concerns, not circulated broadly.</p><p><strong>Next:</strong> follow the team responsible for handling the concern&#39;s instructions. If the normal account may be accessed or controlled without permission, use the known alternative contact route. Do not include the password itself.</p></div>";say('Useful first report assembled. Nothing was sent.');};}


function moduleSections(m){if(m.id!=='law')return m.sections.map(s=>`<section><h2>${esc(s[0])}</h2><p>${esc(MODULE_SUMMARIES[m.id]?.[s[0]]||s[1])}</p><details class="explanation"><summary>More detail and examples</summary><p>${esc(s[1])}</p><ul>${s[2].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details></section>`).join('');return `<section><h2>Your first action: report as soon as you can</h2><p>If personal information may have been lost, shared incorrectly or accessed without permission, tell the known person responsible for security concerns as soon as you can. Give facts and follow the local procedure. Do not wait 72 hours or decide by yourself whether the regulator or affected people must be told.</p><ul><li>Use a known alternative if the normal contact route is unavailable.</li><li>The approved team assesses risk, keeps the record and decides who outside the organisation must be told.</li><li>Training completion is not formal approval or a promise that legal requirements are met.</li></ul></section><details class="legal-detail"><summary>For managers: current legal detail and course limits</summary>${m.sections.map(s=>`<section><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p><ul>${s[2].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section>`).join('')}</details>`;}

function useAtWork(){return `<section class="panel no-print" aria-labelledby="work-next"><h2 id="work-next">Use this at work</h2><p>Optional and unscored. Talk through these with your manager or a colleague. Keep workplace details outside this course.</p><ol><li><strong>Find your real reporting route.</strong> Who would you tell, and what is the backup if that person or your work email is unavailable?</li><li><strong>Choose one habit to use.</strong> For example, check changed payment details through a known contact before acting.</li><li><strong>Make safe action easier.</strong> What could get in the way? Agree one practical fix and who will take it forward.</li></ol><p class="hint">Passing shows completion of this course, not proof of identity or safe behaviour at work. Act on a live concern now, using your workplace route.</p><a href="#practice">Try optional practice with changed facts</a></section>`;}
function team(){setPage(`<div class="section-head"><p class="eyebrow">For owners and managers</p><h1>Run this with your team.</h1><p>Free practice for staff at UK small businesses. Staff make choices in 10 fictional work tasks, review 8 learning modules and take a 16-question assessment.</p></div><p class="hint" id="team-step" aria-live="polite">Step 1 of 3 · Set up</p><div class="module-content"><section data-team-step="0"><h2>Set up the local rules</h2><p>Before staff start, explain the real reporting contact, backup and urgent route, including what to use if work email is unavailable. Agree approved devices, tools, payment and information-sharing rules.</p><p>Use the guide's workplace-rules sheet. Keep names and workplace details in your own approved documents, not in this course.</p><div class="actions"><a class="button" href="Facilitator-Guide.pdf">Read the manager guide (PDF)</a><a class="button" href="Facilitator-Guide.docx">Edit the workplace-rules sheet (Word)</a></div><p><a href="#manager">Rehearse receiving a security report</a> with the responsible person before staff use. A live concern must not wait for training.</p><div class="actions"><button class="primary" data-team-next="1">Next: time and support</button></div></section><section data-team-step="1" hidden><h2>Give staff time and support</h2><p>Plan about 45-60 minutes for the course plus 15 minutes for discussion. This is an estimate, not a time tested with real learners. Allow extra time, breaks or shorter sessions.</p><p>Staff can work individually or discuss choices in pairs. No timer or account is needed. Optional saving stays in this browser on this device; do not enable it on a shared device.</p><p><a href="Learning-Transcript.html">Use the reading version</a> for individual or assisted discussion if the interactive course is not suitable. Check it works for your staff and arrange support.</p><details><summary>Brief your staff</summary><p>We are using a fictional working day to practise checking requests and reporting concerns. This is a learning session, not a test of how quickly you can finish. Use our agreed reporting contact and backup for real concerns. Do not enter real passwords, customer information or live security problem details into the course. Ask for help or take a break when you need one.</p><p class="hint">Adapt this briefing to your workplace. Share the course link through your normal staff channel.</p></details><div class="actions"><button class="text-link" data-team-next="0">Back to setup</button><button class="primary" data-team-next="2">Next: after the course</button></div></section><section data-team-step="2" hidden><h2>Turn practice into a useful action</h2><p>Afterwards, ask staff to explain their reporting route and choose one habit to use. Discuss what might get in the way, then agree a practical fix and who will take it forward. The guide includes a 15-minute discussion plan.</p><p>Staff practise checking unusual requests, slowing down under pressure and reporting facts without secrets. Completion does not prove they will do this at work.</p><details><summary>Completion records and course limits</summary><p>The browser can print a completion record after a score of at least 13 out of 16. The name is optional and used only for printing. Identity and results are not independently checked, and learners can change browser records.</p><p>No activity or results are sent to us or your business. If you need formal training records, use an approved employer process and explain what is recorded and why.</p><p>This is awareness practice, not an officially recognised qualification, official endorsement, a promise of legal compliance or a complete plan for handling security problems. Your local rules and security protections still matter.</p></details><div class="actions"><button class="text-link" data-team-next="1">Back to time and support</button><a class="button primary" href="#day">Open the staff course</a></div></section><p><a href="#home">Back to overview</a></p><p class="hint">No account or payment is needed to play. <a href="https://payhip.com/b/1y26E" target="_blank" rel="noopener noreferrer">Optional free download</a>: the download platform has separate checkout/contact fields.</p></div>`);document.querySelectorAll('[data-team-next]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.teamNext);document.querySelectorAll('[data-team-step]').forEach(s=>s.hidden=Number(s.dataset.teamStep)!==i);document.getElementById('team-step').textContent=['Step 1 of 3 · Set up','Step 2 of 3 · Time and support','Step 3 of 3 · After the course'][i];const h=document.querySelector('[data-team-step="'+i+'"] h2');h.tabIndex=-1;h.focus();h.scrollIntoView({block:'start'});});}

function manager(){setPage(`<div class="section-head"><p class="eyebrow">For managers · rehearse before staff use</p><h1>When someone reports a concern.</h1><p>This card helps a manager receive a security report. It is not a complete plan for handling security problems. Use your organisation's agreed plan and approved person responsible for handling the concern. A live concern must not wait until training ends.</p></div><div class="module-content"><ol class="intake"><li><h2>Thank them and raise it as soon as you can</h2><p>Thank the reporter. Contact the person responsible for handling the concern or backup as soon as you can. Use the urgent route out of hours, or the known alternative if email may be accessed or controlled without permission.</p></li><li><h2>Record facts, not secrets</h2><p>Record the time, device or service, actions, observations and data involved. Say what is unknown. Never collect passwords, codes or unnecessary personal information.</p></li><li><h2>Use the existing plan to limit harm</h2><p>The person responsible for handling the concern directs how to limit further harm and restore safe work. Follow the plan, preserve evidence and limit the people who can receive it. Do not improvise resets, investigation tools or messages to people outside the organisation.</p></li><li><h2>Name the responsible person and next update</h2><p>Name the responsible person, contact route and next update time. Keep the record in the approved secure location. Posting in a group chat does not prove someone has accepted responsibility.</p></li><li><h2>Leave legal decisions and outside messages to approved staff</h2><p>The approved team assesses risk and follows the organisation's legal role. The organisation deciding why and how personal information is used assesses regulator reporting, records every personal-data breach and the reasons for its decisions, even when no regulator report is needed, and tells affected people when the risk is high. One handling that information for it following its instructions tells it without unnecessary delay after becoming aware of a breach, regardless of the regulator reporting threshold. The deciding organisation's required regulator report is due without unnecessary delay and, where possible, within 72 hours of its awareness. Never delay internal reporting to wait for that deadline. A personal-data breach means a security problem involving loss, destruction, change, damage, improper sharing or access to information about identifiable people; unavailability can count too. It must tell the regulator unless a risk to people's rights and freedoms is unlikely. This assessment includes possible harm to privacy, fraud, discrimination and other harm to the people affected.</p></li></ol><div class="notice"><h3>Practise with one fictional report</h3><p>Agree the rehearsal with your person responsible for handling the concern before staff play, including who is involved and when. Use a clearly fictional, practice-only report through your internal reporting route. Label it as a rehearsal. Confirm someone answers, accepts responsibility for the report and knows where to record the security problem securely. Use no real information, passwords or sign-in codes. Do not contact anyone outside the organisation, customers or banks. Fix any gaps before staff use.</p></div><details><summary>Setup checklist and sources</summary><ul><li>Responsible person and backup</li><li>Urgent/out-of-hours contact</li><li>Alternative if normal email or sign-in is unavailable</li><li>Approved safe place to keep security reports</li><li>Local steps for limiting harm and restoring safe work on devices and accounts</li></ul><p>Use the <a href="Facilitator-Guide.docx">editable facilitator guide</a> to fill in the local details. Do not enter them or live security problem information into this course.</p><p class="hint">Based on <a href="https://www.ncsc.gov.uk/collection/small-business-guidance--response-and-recovery" target="_blank" rel="noopener noreferrer">UK National Cyber Security Centre guidance for handling security problems and restoring safe work</a> and <a href="https://ico.org.uk/for-organisations/advice-for-small-organisations/personal-data-breaches/72-hours-how-to-respond-to-a-personal-data-breach/" target="_blank" rel="noopener noreferrer">UK data protection regulator first-72-hours guidance</a>. Choosing contacts and update times is a workplace process, not an additional legal rule. Checked ${META.checked}.</p></details></div>`);}

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();const main=document.getElementById('main');main.focus();main.scrollIntoView({block:'start'});});
window.addEventListener('hashchange',()=>{render();save();syncOfficeSaving();});window.addEventListener('afterprint',()=>document.body.classList.remove('print-certificate'));if(!location.hash&&resumeRoute)history.replaceState(null,'','#'+resumeRoute);setupOfficeSession();render();

function saveQuizDraft(){state.quizDraft={answers:{...assessmentAnswers},index:quizIndex};save();}
function focusDecision(){const target=document.querySelector('.decision:not([hidden])')||document.querySelector('.prepared-report');if(target){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.scrollIntoView({block:'nearest'});}}

// Course workspace navigation, optional guide and same-browser progress controls.
function validOfficeRoute(value){return typeof value==='string'&&(['home','day','library','assessment','help','practice','manager','team'].includes(value)||EVENTS.some(e=>value==='day/'+e.id)||MODULES.some(m=>value==='library/'+m.id));}
function officeSavingText(){return unrecognisedSaved?'Unrecognised saved work is preserved. This page cannot overwrite or reset it.':otherTabChanged?'Another tab changed saved work. Saving is off here. Keep this page open to preserve unsaved work, or reload for the newer saved workspace.':clearFailed?'Saved work could not be removed. Old progress may return on reload. Clear this site in browser settings before leaving a shared device.':!storageAvailable?'Saving is unavailable. Current work remains only on this open page. Keep it open before copying any fictional work you need.':state.save?'Saving is on. Progress and your current workspace save in this browser.':'Saving is off. Work remains only on this open page.';}
function syncOfficeSaving(){const box=document.getElementById('office-remember');if(!box)return;box.checked=state.save;box.disabled=!storageAvailable||otherTabChanged||unrecognisedSaved;document.getElementById('office-saving-status').textContent=officeSavingText();const existing=document.getElementById('remember');if(existing){existing.checked=state.save;existing.disabled=box.disabled;}const hint=document.getElementById('save-state');if(hint)hint.textContent=officeSavingText();}
function updateOfficeGuide(){const guide=document.getElementById('office-guide');if(guide)guide.hidden=!officeGuide;document.querySelector('.office-shell')?.classList.toggle('office-guide-closed',!officeGuide);document.getElementById('office-guide-toggle').setAttribute('aria-expanded',String(officeGuide));save();}
function resetOfficeWork(){if(!confirm('Reset saved progress in this browser? This cannot be undone.'))return;if(!clearStoredProgress())return;state=fresh();assessmentAnswers={};quizSubmitted=false;triageState={};practiceIndex=0;changeIndex=0;changeStage=0;changeAnswer=null;reviewIndex=0;showTasks=false;quizIndex=0;inspectState={};reportDraft=[];workStage={};document.getElementById('office-saving').hidden=true;location.hash='home';render();say('Saved progress reset.');}
function setupOfficeSession(){document.getElementById('office-menu-toggle').onclick=()=>{const menu=document.getElementById('office-menu');menu.hidden=!menu.hidden;document.getElementById('office-menu-toggle').setAttribute('aria-expanded',String(!menu.hidden));};document.getElementById('office-save-open').onclick=()=>{officeSaveOpener=document.activeElement;document.getElementById('office-saving').hidden=false;syncOfficeSaving();document.getElementById('office-remember').focus();document.getElementById('office-saving').scrollIntoView({block:'nearest'});};document.getElementById('office-save-close').onclick=()=>{document.getElementById('office-saving').hidden=true;(officeSaveOpener?.isConnected?officeSaveOpener:document.getElementById('office-save-open')).focus();};document.getElementById('office-remember').onchange=e=>{if(e.target.checked){state.save=true;save();}else{state.save=false;clearStoredProgress();}syncOfficeSaving();};document.getElementById('office-reset').onclick=resetOfficeWork;document.getElementById('office-guide-toggle').onclick=()=>{officeGuide=!officeGuide;updateOfficeGuide();};document.getElementById('office-guide-toggle').setAttribute('aria-expanded',String(officeGuide));}

function setOfficeTaskList(open,moveFocus){showTasks=open;const layout=document.querySelector('.day-layout');if(!layout)return;layout.classList.toggle('task-list-open',open);layout.querySelector('.tasklist').classList.toggle('collapsed',!open);const toggle=document.getElementById('toggle-tasks');toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'Return to current task':'All tasks';if(moveFocus){if(open){layout.querySelector('.task.selected')?.focus();}else{const title=document.getElementById('task-title');title.setAttribute('tabindex','-1');title.focus({preventScroll:true});}}}

document.addEventListener('keydown',e=>{if(e.key==='Tab')document.body.classList.add('keyboard-navigation');});document.addEventListener('pointerdown',()=>document.body.classList.remove('keyboard-navigation'));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.getElementById('office-menu').hidden){document.getElementById('office-menu').hidden=true;document.getElementById('office-menu-toggle').setAttribute('aria-expanded','false');document.getElementById('office-menu-toggle').focus();}});
